ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	status: 404,
	code: "NOT_FOUND",
	message: {
		message: "Process not found for command: " ++ (vars.tipoProceso default "")
	},
	messageServer: "",
	cause: [{
		origin: "common-papi-services-v2",
		message: "No process mapped for uriParameter command='" ++ (vars.tipoProceso default "") ++ "'"
	}]
}

ee:variables.ee:set-variable:
%dw 2.0
output application/java
var body = payload default {}
var nonEmptyRequired = ["orderNumber", "procedure", "serviceAccountId", "serviceId", "crm", "technology"]
var missingNonEmpty = nonEmptyRequired filter ((f) -> isEmpty(body[f] default ""))
var crmOk = isEmpty(body.crm default "") or (["SUMA", "SALESFORCE"] contains body.crm)
var techOk = isEmpty(body.technology default "") or (["1", "2", "3"] contains (body.technology as String))
var procOk = isEmpty(body.procedure default "") or (["Suspend", "Resume", "Disconnect", "Reconnect", "Terminate"] contains body.procedure)
---
(missingNonEmpty map ((f) -> "Required field " ++ f ++ " not specified"))
++ (if (!crmOk) ["Invalid value for crm. Expected: SUMA, SALESFORCE"] else [])
++ (if (!techOk) ["Invalid value for technology. Expected: 1, 2, 3"] else [])
++ (if (!procOk) ["Invalid value for procedure. Expected: Suspend, Resume, Disconnect"] else [])

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	status: 400,
	code: "REQUEST_ERROR",
	message: {
		message: "No Azure queue mapped for procedure: " ++ (vars.inputPayload.procedure default payload.procedure default "")
	},
	messageServer: "",
	cause: [{
		origin: "common-papi-services-v2",
		message: "Expected procedure Suspend|Resume|Disconnect mapped to collection-command-process-* queues"
	}]
}

%dw 2.0
output application/json
---
{
	status: 400,
	code: "REQUEST_ERROR",
	message: {
		message: vars.validationErrors joinBy "; "
	},
	messageServer: "",
	cause: [{
		origin: "common-papi-services-v2",
		message: "Topic commands body validation failed"
	}]
}
